package dev.kristian.nullmod.client.it;

import dev.kristian.nullmod.entity.it.ItAnimation;
import dev.kristian.nullmod.entity.it.ItEntity;
import dev.kristian.nullmod.entity.it.ItKillPath;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.minecraft.client.model.HierarchicalModel;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.core.BlockPos;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.Entity;

/**
 * IT's model and every move it makes, all procedural. The geometry is {@link ItModelLayer}
 * (generated by {@code tools/gen_it.py}, whose pose solver this class mirrors line by line).
 * <ul>
 * <li>The torso blends between an upright, hunched stance, a gallop on all fours and a deep crouch;
 * the head is held level and looks where IT looks, in jerks.</li>
 * <li>The legs are placed by two-bone inverse kinematics (the shin and the extra joint below it act
 * as one rigid lower leg) onto gait paths: planted while they bear weight, lifted in an arc
 * otherwise, so the feet stay on the ground.</li>
 * <li>The arms hang and swing when it walks, become front legs at a gallop, and reach for whatever
 * the moment needs: the victim it holds, the chest it drives its blades through, the wall beside a
 * window, the wall it scrapes. Same inverse kinematics, in three dimensions, elbows out.</li>
 * <li>The tentacles writhe in layered waves, never in step; they stream back at speed, flare when
 * it screams and reach for the victim while it feeds. Joints snap out of place for a moment now
 * and then, and everything shudders after a blow.</li>
 * </ul>
 * Model space is in pixels: +X is IT's left, +Y down, -Z its front, the ground at y = 24.
 * Render thread only (one instance per renderer, posed right before each entity is drawn).
 */
final class ItModel extends HierarchicalModel<ItEntity> {
    static final float STAND_HIP_Y = -36.0F;
    static final float RUN_HIP_Y = -24.0F;
    static final float CROUCH_HIP_Y = -21.0F;
    static final float ANKLE_Y = 22.0F;
    static final float HAND_Y = 15.0F;
    static final float LEG_THIGH = 24.0F;
    static final float LEG_SHIN = 26.0F;
    static final float LEG_CANNON = 18.0F;
    static final float LEG_CANNON_BEND = -0.75F;
    static final float ARM_UPPER = 31.0F;
    static final float ARM_REST = 30.0F + 10.0F + 5.0F;
    private static final float LOWER_Y = LEG_SHIN + LEG_CANNON * Mth.cos(LEG_CANNON_BEND);
    private static final float LOWER_Z = LEG_CANNON * Mth.sin(LEG_CANNON_BEND);
    private static final float LEG_LOWER = (float) Math.sqrt(LOWER_Y * LOWER_Y + LOWER_Z * LOWER_Z);
    private static final float LEG_DELTA = (float) Math.atan2(LOWER_Z, LOWER_Y);
    private static final float TAU = Mth.TWO_PI;
    /** Number of joints {@link ItAnimation#twitchJoint} can name. */
    static final int TWITCH_JOINTS = 8;

    private final ModelPart root;
    private final ModelPart hips;
    private final ModelPart spine;
    private final ModelPart chest;
    private final ModelPart neck;
    private final ModelPart head;
    private final ModelPart jaw;
    private final ModelPart sternum;
    private final ModelPart[] thigh = new ModelPart[2];
    private final ModelPart[] shin = new ModelPart[2];
    private final ModelPart[] cannon = new ModelPart[2];
    private final ModelPart[] foot = new ModelPart[2];
    private final ModelPart[] shoulder = new ModelPart[2];
    private final ModelPart[] arm = new ModelPart[2];
    private final ModelPart[] fore = new ModelPart[2];
    private final ModelPart[] wrist = new ModelPart[2];
    private final ModelPart[] hand = new ModelPart[2];
    private final ModelPart[][] finger = new ModelPart[2][4];
    private final ModelPart[][] fingerTip = new ModelPart[2][4];
    private final ModelPart[][] chestTentacles;
    private final ModelPart[][] backTentacles;
    private final ModelPart[] ribs;
    private final ModelPart[] parts;
    private final ModelPart[] twitchJoints;
    private final ModelPart[] legChain;
    private final ModelPart[][] armChain = new ModelPart[2][];
    private final ModelPart[] faceChain;

    // Scratch space for the kinematics (render thread only).
    private final float[] rot = new float[9];
    private final float[] local = new float[9];
    private final float[] product = new float[9];
    private final float[] origin = new float[3];
    private float solvedX;
    private float solvedY;
    private float solvedZ;
    private float solvedBend;
    private float partialTick;

    ItModel(ModelPart root) {
        this.root = root;
        this.hips = root.getChild("hips");
        this.spine = hips.getChild("spine");
        this.chest = spine.getChild("chest");
        this.neck = chest.getChild("neck");
        this.head = neck.getChild("head");
        this.jaw = head.getChild("jaw");
        this.sternum = chest.getChild("sternum");
        String[] sides = {"l", "r"};
        for (int s = 0; s < 2; s++) {
            String side = sides[s];
            thigh[s] = hips.getChild("thigh_" + side);
            shin[s] = thigh[s].getChild("shin_" + side);
            cannon[s] = shin[s].getChild("cannon_" + side);
            foot[s] = cannon[s].getChild("foot_" + side);
            shoulder[s] = chest.getChild("shoulder_" + side);
            arm[s] = shoulder[s].getChild("arm_" + side);
            fore[s] = arm[s].getChild("fore_" + side);
            wrist[s] = fore[s].getChild("wrist_" + side);
            hand[s] = wrist[s].getChild("hand_" + side);
            for (int k = 0; k < 4; k++) {
                finger[s][k] = hand[s].getChild("finger" + k);
                fingerTip[s][k] = finger[s][k].getChild("tip");
            }
        }
        this.chestTentacles = new ModelPart[3][];
        for (int i = 0; i < chestTentacles.length; i++) {
            chestTentacles[i] = chain(chest.getChild("ct" + i));
        }
        this.backTentacles = new ModelPart[4][];
        for (int i = 0; i < backTentacles.length; i++) {
            backTentacles[i] = chain(chest.getChild("bt" + i));
        }
        List<ModelPart> ribList = new ArrayList<>();
        for (int k = 0; k < 4; k++) {
            ribList.add(chest.getChild("rib_l" + k));
        }
        for (int k = 0; k < 3; k++) {
            ribList.add(chest.getChild("rib_r" + k));
        }
        this.ribs = ribList.toArray(new ModelPart[0]);
        this.parts = root.getAllParts().toArray(ModelPart[]::new);
        this.twitchJoints = new ModelPart[]{head, jaw, neck, shoulder[0], shoulder[1], fore[0], fore[1], chest};
        this.legChain = new ModelPart[]{hips};
        this.armChain[0] = new ModelPart[]{hips, spine, chest, shoulder[0]};
        this.armChain[1] = new ModelPart[]{hips, spine, chest, shoulder[1]};
        this.faceChain = new ModelPart[]{hips, spine, chest, neck, head};
    }

    private static ModelPart[] chain(ModelPart first) {
        List<ModelPart> segments = new ArrayList<>();
        ModelPart part = first;
        segments.add(part);
        while (part.hasChild("s")) {
            part = part.getChild("s");
            segments.add(part);
        }
        return segments.toArray(new ModelPart[0]);
    }

    @Override
    public ModelPart root() {
        return root;
    }

    @Override
    public void prepareMobModel(ItEntity entity, float limbSwing, float limbSwingAmount, float partialTick) {
        this.partialTick = partialTick;
    }

    // ================================================================== posing

    @Override
    public void setupAnim(ItEntity it, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {
        for (ModelPart part : parts) {
            part.resetPose();
        }
        ItAnimation a = it.animation();
        float pt = partialTick;
        float t = ageInTicks;
        float speed = Mth.lerp(pt, a.speedO, a.speed);
        float run = Mth.lerp(pt, a.runO, a.run);
        float ph = Mth.lerp(pt, a.phaseO, a.phase);
        float crouch = Mth.lerp(pt, a.crouchO, a.crouch);
        float scream = Mth.lerp(pt, a.screamO, a.scream);
        float scrape = Mth.lerp(pt, a.scrapeO, a.scrape);
        float lookYaw = Mth.lerp(pt, a.headYawO, a.headYaw);
        float lookPitch = Mth.lerp(pt, a.headPitchO, a.headPitch);

        // What the moment asks of the arms, the jaw and the tentacles.
        float jawOpen = 0.0F;
        float grip = 0.0F;
        float pierce = 0.0F;
        float reach = 0.0F;
        float neckExtra = 0.0F;
        float rightWeight = 0.0F;
        float leftWeight = 0.0F;
        float rx = 0.0F;
        float ry = 0.0F;
        float rz = 0.0F;
        float lx = 0.0F;
        float ly = 0.0F;
        float lz = 0.0F;
        int stage = it.killStage();
        Entity victim = stage != ItEntity.KILL_NONE ? it.getFirstPassenger() : null;
        if (victim != null) {
            float kt = it.killTicks() + pt;
            double ex = Mth.lerp(pt, it.xo, it.getX());
            double ey = Mth.lerp(pt, it.yo, it.getY());
            double ez = Mth.lerp(pt, it.zo, it.getZ());
            float bodyYaw = Mth.rotLerp(pt, it.yBodyRotO, it.yBodyRot);
            double vx = Mth.lerp(pt, victim.xo, victim.getX());
            double vy = Mth.lerp(pt, victim.yo, victim.getY());
            double vz = Mth.lerp(pt, victim.zo, victim.getZ());
            float height = victim.getBbHeight();
            toModel(vx - ex, vy + height * 0.53 - ey, vz - ez, bodyYaw);
            rx = origin[0];
            ry = origin[1];
            rz = origin[2];
            toModel(vx - ex, vy + height * 0.7 - ey, vz - ez, bodyYaw);
            float cx = origin[0];
            float cy = origin[1];
            float cz = origin[2];
            rightWeight = smooth(kt / 6.0F);
            grip = smooth((kt - 3.0F) / 8.0F);
            crouch = Math.max(crouch, kt < ItKillPath.SEIZE_END ? 0.9F : 0.9F * (1.0F - smooth((kt - ItKillPath.SEIZE_END) / 18.0F)));
            jawOpen = 0.2F + 0.3F * smooth((kt - ItKillPath.SEIZE_END) / 25.0F);
            float windup = ItKillPath.PIERCE_AT - 8.0F;
            if (kt >= windup) {
                // The other hand comes back beside the victim, then through its chest.
                float back = smooth((kt - windup) / 6.0F);
                float strike = smooth((kt - ItKillPath.PIERCE_AT + 1.0F) / 2.5F);
                lx = cx + 12.0F * (1.0F - strike);
                ly = cy - 4.0F * (1.0F - strike);
                lz = cz + 22.0F * (1.0F - strike) - 8.0F * strike;
                leftWeight = back;
                pierce = strike;
                if (kt > ItKillPath.DEVOUR_START + 10.0F) {
                    // The blades come out and that hand grips the victim's side while it feeds.
                    float hold = smooth((kt - ItKillPath.DEVOUR_START - 10.0F) / 10.0F);
                    lx = Mth.lerp(hold, lx, cx + 9.0F);
                    ly = Mth.lerp(hold, ly, cy + 2.0F);
                    lz = Mth.lerp(hold, lz, cz + 3.0F);
                    pierce *= 1.0F - hold;
                }
            }
            if (kt >= ItKillPath.DEVOUR_START) {
                float devour = smooth((kt - ItKillPath.DEVOUR_START) / 8.0F);
                jawOpen = Mth.lerp(devour, jawOpen, 1.35F);
                // Bites: the jaw slams shut on the beat.
                jawOpen -= 0.9F * (bite(kt, ItKillPath.BITE_AT) + bite(kt, ItKillPath.TEAR_AT) + 0.6F * bite(kt, ItKillPath.SWALLOW_AT));
                neckExtra = 0.35F * devour;
                reach = devour;
            } else if (kt >= ItKillPath.LIFT_END) {
                reach = 0.4F;
            }
        } else {
            int action = it.action();
            Optional<BlockPos> focus = it.focus();
            if (focus.isPresent() && (action == ItEntity.ACTION_WINDOW || action == ItEntity.ACTION_SCRAPE)) {
                BlockPos pos = focus.get();
                double ex = Mth.lerp(pt, it.xo, it.getX());
                double ey = Mth.lerp(pt, it.yo, it.getY());
                double ez = Mth.lerp(pt, it.zo, it.getZ());
                float bodyYaw = Mth.rotLerp(pt, it.yBodyRotO, it.yBodyRot);
                toModel(pos.getX() + 0.5 - ex, pos.getY() + 0.5 - ey, pos.getZ() + 0.5 - ez, bodyYaw);
                float wy = origin[1];
                // The outer face of the wall, seen from IT, is half a block nearer than the block's centre.
                float wz = origin[2] + 8.0F;
                if (action == ItEntity.ACTION_WINDOW) {
                    // Hands flat on the wall either side of the glass.
                    lx = 17.0F;
                    ly = wy - 4.0F;
                    lz = wz + 2.0F;
                    rx = -17.0F;
                    ry = wy - 6.0F;
                    rz = wz + 2.0F;
                    leftWeight = crouch;
                    rightWeight = crouch;
                    neckExtra = Mth.clamp(a.peerDrop * 0.45F, -0.2F, 0.9F) * crouch;
                } else {
                    // One blade arm dragged down the wall, again and again.
                    float stroke = Mth.lerp(pt, a.scrapePhaseO, a.scrapePhase);
                    float down = stroke < 0.75F ? stroke / 0.75F : 1.0F - (stroke - 0.75F) / 0.25F;
                    rx = -7.0F;
                    ry = -44.0F + 50.0F * down;
                    rz = wz + 3.0F;
                    rightWeight = scrape;
                    lx = 15.0F;
                    ly = -20.0F;
                    lz = wz + 4.0F;
                    leftWeight = 0.5F * scrape;
                }
            }
        }

        // ---------------------------------------------------------------- torso
        float breath = Mth.sin(t * 0.09F);
        float bob = 2.2F * run * Mth.sin(2.0F * TAU * ph);
        hips.y = STAND_HIP_Y + (RUN_HIP_Y - STAND_HIP_Y) * run + (CROUCH_HIP_Y - STAND_HIP_Y) * crouch * (1.0F - run) + bob;
        float hipsPitch = 0.12F * run + 0.1F * crouch;
        float spinePitch = 0.35F + 0.32F * run + 0.42F * crouch + 0.015F * breath;
        float chestPitch = 0.25F + 0.26F * run + 0.36F * crouch + 0.02F * breath + 0.07F * run * Mth.sin(2.0F * TAU * ph + 0.6F);
        hips.xRot = hipsPitch;
        spine.xRot = spinePitch;
        chest.xRot = chestPitch;
        chest.zRot = 0.03F * Mth.sin(t * 0.05F);
        float neckPitch = 0.55F - 0.45F * run + 0.2F * crouch + 0.25F * scream + neckExtra;
        float torso = hipsPitch + spinePitch + chestPitch;
        neck.xRot = neckPitch;
        head.xRot = -(torso + neckPitch) + 0.3F - 0.15F * run + lookPitch - 0.25F * scream + 0.35F * neckExtra;
        head.yRot = lookYaw;
        head.zRot = 0.14F * scream * Mth.sin(t * 1.9F);
        jaw.xRot = 0.35F + 0.15F * breath * (1.0F - scream) + jawOpen + 1.0F * scream;
        for (int i = 0; i < ribs.length; i++) {
            // The open ribcage heaves with its breath.
            ribs[i].yRot += (i < 4 ? -1.0F : 1.0F) * (0.05F * breath + 0.12F * scream * Mth.sin(t * 1.3F + i));
        }
        sternum.zRot += 0.08F * Mth.sin(t * 0.07F);

        // ---------------------------------------------------------------- legs
        float duty = ItGait.duty(run);
        float lift = (5.0F + 9.0F * run) * Math.min(1.0F, speed / 0.12F);
        float stride = ItGait.stride(speed, duty);
        for (int s = 0; s < 2; s++) {
            float sx = s == 0 ? 1.0F : -1.0F;
            float p = ItGait.frac(ph + ItGait.legOffset(s, run));
            float zc = 2.0F + 3.0F * run - 5.0F * crouch;
            float x = sx * (7.0F + 2.5F * crouch);
            float y;
            float z;
            float toe;
            if (p < duty) {
                float sp = p / duty;
                z = zc - stride * 0.5F + stride * sp;
                y = ANKLE_Y;
                toe = 0.0F;
            } else {
                float sp = (p - duty) / (1.0F - duty);
                z = zc + stride * 0.5F - stride * smooth(sp);
                y = ANKLE_Y - lift * Mth.sin(Mth.PI * sp);
                toe = 0.55F * Mth.sin(Mth.PI * sp);
            }
            solveLeg(s, x, y, z, toe);
        }

        // ---------------------------------------------------------------- arms
        for (int s = 0; s < 2; s++) {
            float sx = s == 0 ? 1.0F : -1.0F;
            float swing = 0.3F * Math.min(1.0F, speed / 0.2F) * (1.0F - run) * Mth.sin(TAU * (ph + ItGait.ARM_WALK[s]));
            float ax = -torso - 0.1F + swing - 0.45F * scream;
            float ay = 0.0F;
            float az = -0.1F * sx - 0.55F * sx * scream;
            float bend = -0.25F - 0.3F * scream;
            float planted = 0.0F;
            if (run > 0.01F) {
                float p = ItGait.frac(ph + ItGait.ARM_RUN[s]);
                frame(armChain[s], 4);
                float zc = origin[2] - 18.0F;
                float astride = stride * 0.85F;
                float y;
                float z;
                if (p < duty) {
                    float sp = p / duty;
                    z = zc - astride * 0.5F + astride * sp;
                    y = HAND_Y;
                    planted = Mth.sin(Mth.PI * sp);
                } else {
                    float sp = (p - duty) / (1.0F - duty);
                    z = zc + astride * 0.5F - astride * smooth(sp);
                    y = HAND_Y - (6.0F + 14.0F * run) * Mth.sin(Mth.PI * sp);
                }
                solveArm(s, sx * 15.0F, y, z, sx * 0.7F, -0.4F, 1.0F);
                ax += (solvedX - ax) * run;
                ay += (solvedY - ay) * run;
                az += (solvedZ - az) * run;
                bend += (solvedBend - bend) * run;
            }
            float weight = s == 0 ? leftWeight : rightWeight;
            if (weight > 0.0F) {
                if (s == 0) {
                    solveArm(s, lx, ly, lz, sx * 0.6F, 0.8F, 0.3F);
                } else {
                    solveArm(s, rx, ry, rz, sx * 0.6F, 0.8F, 0.3F);
                }
                ax += (solvedX - ax) * weight;
                ay += (solvedY - ay) * weight;
                az += (solvedZ - az) * weight;
                bend += (solvedBend - bend) * weight;
            }
            arm[s].xRot = ax;
            arm[s].yRot = ay;
            arm[s].zRot = az;
            fore[s].xRot = bend;
            wrist[s].xRot = -0.1F * (1.0F - run) * (1.0F - weight);
            float g = s == 1 ? grip : 0.0F;
            float pr = s == 0 ? pierce : 0.0F;
            for (int k = 0; k < 4; k++) {
                float spread = (k - 1.5F) * sx * (0.1F + 0.25F * scream + 0.15F * planted * run) * (1.0F - pr);
                finger[s][k].xRot = -0.25F - 0.4F * planted * run - 1.0F * g + 0.2F * pr;
                finger[s][k].zRot = spread;
                fingerTip[s][k].xRot = -0.35F - 0.9F * g + 0.3F * pr + 0.2F * planted * run;
            }
        }

        // ---------------------------------------------------------------- tentacles
        tentacles(chestTentacles, false, t, run, scream, reach);
        tentacles(backTentacles, true, t, run, scream, reach);

        // ---------------------------------------------------------------- broken
        if (a.twitchTicks > 0 && a.twitchJoint >= 0 && a.twitchJoint < twitchJoints.length) {
            float left = (a.twitchTicks - pt) / Math.max(1.0F, a.twitchLength);
            float amount = Mth.clamp(left, 0.0F, 1.0F);
            ModelPart joint = twitchJoints[a.twitchJoint];
            joint.xRot += a.twitchX * amount;
            joint.zRot += a.twitchZ * amount;
        }
        if (a.jolt > 0.01F) {
            float j = a.jolt;
            chest.xRot += Mth.sin(t * 2.9F) * 0.05F * j;
            chest.zRot += Mth.cos(t * 3.3F) * 0.06F * j;
            head.zRot += Mth.sin(t * 4.1F) * 0.12F * j;
            neck.xRot += Mth.cos(t * 3.7F) * 0.06F * j;
        }
    }

    private static float bite(float kt, int at) {
        float d = kt - at;
        return d < 0.0F || d > 6.0F ? 0.0F : (d < 1.5F ? d / 1.5F : 1.0F - (d - 1.5F) / 4.5F);
    }

    private static void tentacles(ModelPart[][] chains, boolean back, float t, float run, float scream, float reach) {
        for (int i = 0; i < chains.length; i++) {
            ModelPart[] segments = chains[i];
            for (int k = 0; k < segments.length; k++) {
                float along = (k + 1) / 7.0F;
                float amp = (0.07F + 0.15F * along) * (back ? 1.0F : 1.4F) * (1.0F + 1.5F * scream + 0.8F * reach);
                float speed = (0.10F + 0.021F * i) * (1.0F + 1.2F * scream + 0.6F * run);
                float x = amp * Mth.sin(t * speed + i * 2.1F + k * 0.7F);
                float y = amp * Mth.cos(t * speed * 0.83F + i * 1.3F + k * 0.55F);
                if (back) {
                    x += -0.16F * run * along + (k == 0 ? 0.3F * scream : 0.0F);
                } else {
                    x += 0.1F * run * along - 0.25F * reach * (k == 0 ? 1.0F : 0.3F);
                }
                segments[k].xRot += x;
                segments[k].yRot += y;
            }
        }
    }

    private static float smooth(float t) {
        float c = Mth.clamp(t, 0.0F, 1.0F);
        return c * c * (3.0F - 2.0F * c);
    }

    // ================================================================== kinematics

    /**
     * A world offset from IT's feet into model pixels, for an entity whose body faces
     * {@code bodyYaw}: the inverse of what LivingEntityRenderer does (turn by 180 - yaw, flip x and
     * y, lift by 1.501). Result in {@link #origin}.
     */
    private void toModel(double dx, double dy, double dz, float bodyYaw) {
        float theta = (180.0F - bodyYaw) * Mth.DEG_TO_RAD;
        float cos = Mth.cos(theta);
        float sin = Mth.sin(theta);
        float x = (float) (dx * cos - dz * sin);
        float z = (float) (dx * sin + dz * cos);
        origin[0] = -x * 16.0F;
        origin[1] = (float) (1.501 - dy) * 16.0F;
        origin[2] = z * 16.0F;
    }

    /** Model-space rotation ({@link #rot}, row-major) and origin ({@link #origin}) of the last part of a chain. */
    private void frame(ModelPart[] chain, int count) {
        rot[0] = 1.0F;
        rot[1] = 0.0F;
        rot[2] = 0.0F;
        rot[3] = 0.0F;
        rot[4] = 1.0F;
        rot[5] = 0.0F;
        rot[6] = 0.0F;
        rot[7] = 0.0F;
        rot[8] = 1.0F;
        origin[0] = 0.0F;
        origin[1] = 0.0F;
        origin[2] = 0.0F;
        for (int i = 0; i < count; i++) {
            ModelPart p = chain[i];
            float ox = origin[0] + rot[0] * p.x + rot[1] * p.y + rot[2] * p.z;
            float oy = origin[1] + rot[3] * p.x + rot[4] * p.y + rot[5] * p.z;
            float oz = origin[2] + rot[6] * p.x + rot[7] * p.y + rot[8] * p.z;
            origin[0] = ox;
            origin[1] = oy;
            origin[2] = oz;
            rotationZYX(p.xRot, p.yRot, p.zRot, local);
            multiply(rot, local, product);
            System.arraycopy(product, 0, rot, 0, 9);
        }
    }

    /** ModelPart's rotation: Rz * Ry * Rx, row-major. */
    private static void rotationZYX(float x, float y, float z, float[] out) {
        float cx = Mth.cos(x);
        float sx = Mth.sin(x);
        float cy = Mth.cos(y);
        float sy = Mth.sin(y);
        float cz = Mth.cos(z);
        float sz = Mth.sin(z);
        out[0] = cz * cy;
        out[1] = cz * sy * sx - sz * cx;
        out[2] = cz * sy * cx + sz * sx;
        out[3] = sz * cy;
        out[4] = sz * sy * sx + cz * cx;
        out[5] = sz * sy * cx - cz * sx;
        out[6] = -sy;
        out[7] = cy * sx;
        out[8] = cy * cx;
    }

    private static void multiply(float[] a, float[] b, float[] out) {
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                out[r * 3 + c] = a[r * 3] * b[c] + a[r * 3 + 1] * b[3 + c] + a[r * 3 + 2] * b[6 + c];
            }
        }
    }

    /**
     * Places a leg so its ankle reaches (x, y, z): the thigh rolls out toward the target, then a
     * two-bone solution in the leg's plane with the knee forward; the extra joint keeps its bend
     * and the foot is turned flat (plus {@code toe}).
     */
    private void solveLeg(int s, float x, float y, float z, float toe) {
        frame(legChain, 1);
        ModelPart t = thigh[s];
        float hipX = origin[0] + rot[0] * t.x + rot[1] * t.y + rot[2] * t.z;
        float hipY = origin[1] + rot[3] * t.x + rot[4] * t.y + rot[5] * t.z;
        float hipZ = origin[2] + rot[6] * t.x + rot[7] * t.y + rot[8] * t.z;
        float dx = x - hipX;
        float dy = y - hipY;
        float dz = z - hipZ;
        float splay = (float) -Math.atan2(dx, dy);
        float down = (float) Math.sqrt(dx * dx + dy * dy);
        float l1 = LEG_THIGH;
        float l2 = LEG_LOWER;
        float dist = Mth.clamp((float) Math.sqrt(down * down + dz * dz), Math.abs(l1 - l2) + 0.5F, l1 + l2 - 0.5F);
        float phi = (float) Math.atan2(dz, down);
        float cosA = (l1 * l1 + dist * dist - l2 * l2) / (2.0F * l1 * dist);
        float a1 = phi - (float) Math.acos(Mth.clamp(cosA, -1.0F, 1.0F));
        float ky = l1 * Mth.cos(a1);
        float kz = l1 * Mth.sin(a1);
        float ty = dist * Mth.cos(phi);
        float tz = dist * Mth.sin(phi);
        float a2 = (float) Math.atan2(tz - kz, ty - ky);
        t.xRot = a1 - hips.xRot;
        t.yRot = 0.0F;
        t.zRot = splay;
        shin[s].xRot = (a2 - LEG_DELTA) - a1;
        cannon[s].xRot = LEG_CANNON_BEND;
        foot[s].xRot = toe - (a2 - LEG_DELTA + LEG_CANNON_BEND);
    }

    /**
     * Upper arm rotation (in its parent's frame) and elbow bend that bring the palm to (x, y, z),
     * the elbow pushed toward the pole direction. Results in solvedX/Y/Z and solvedBend.
     */
    private void solveArm(int s, float x, float y, float z, float poleX, float poleY, float poleZ) {
        frame(armChain[s], 4);
        ModelPart upper = arm[s];
        float sx = origin[0] + rot[0] * upper.x + rot[1] * upper.y + rot[2] * upper.z;
        float sy = origin[1] + rot[3] * upper.x + rot[4] * upper.y + rot[5] * upper.z;
        float sz = origin[2] + rot[6] * upper.x + rot[7] * upper.y + rot[8] * upper.z;
        float l1 = ARM_UPPER;
        float l2 = ARM_REST;
        float dx = x - sx;
        float dy = y - sy;
        float dz = z - sz;
        float length = (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
        float nx;
        float ny;
        float nz;
        if (length > 1.0E-4F) {
            nx = dx / length;
            ny = dy / length;
            nz = dz / length;
        } else {
            nx = 0.0F;
            ny = 1.0F;
            nz = 0.0F;
        }
        float dist = Mth.clamp(length, Math.abs(l1 - l2) + 0.5F, l1 + l2 - 0.5F);
        float along = (l1 * l1 + dist * dist - l2 * l2) / (2.0F * dist);
        float h = (float) Math.sqrt(Math.max(0.0F, l1 * l1 - along * along));
        float pd = poleX * nx + poleY * ny + poleZ * nz;
        float qx = poleX - pd * nx;
        float qy = poleY - pd * ny;
        float qz = poleZ - pd * nz;
        float ql = (float) Math.sqrt(qx * qx + qy * qy + qz * qz);
        if (ql > 1.0E-4F) {
            qx /= ql;
            qy /= ql;
            qz /= ql;
        } else {
            qx = 0.0F;
            qy = 0.0F;
            qz = 1.0F;
        }
        float ex = sx + nx * along + qx * h;
        float ey = sy + ny * along + qy * h;
        float ez = sz + nz * along + qz * h;
        float ux = (ex - sx) / l1;
        float uy = (ey - sy) / l1;
        float uz = (ez - sz) / l1;
        float fx = sx + nx * dist - ex;
        float fy = sy + ny * dist - ey;
        float fz = sz + nz * dist - ez;
        float fl = (float) Math.sqrt(fx * fx + fy * fy + fz * fz);
        fx /= fl;
        fy /= fl;
        fz /= fl;
        float fu = fx * ux + fy * uy + fz * uz;
        float wx = fx - fu * ux;
        float wy = fy - fu * uy;
        float wz = fz - fu * uz;
        float wl = (float) Math.sqrt(wx * wx + wy * wy + wz * wz);
        if (wl > 1.0E-4F) {
            wx /= wl;
            wy /= wl;
            wz /= wl;
        } else {
            wx = 0.0F;
            wy = 0.0F;
            wz = -1.0F;
        }
        // The upper arm's axes in model space: Y along the bone, Z away from the bend, X = Y x Z.
        float zx = -wx;
        float zy = -wy;
        float zz = -wz;
        float xx = uy * zz - uz * zy;
        float xy = uz * zx - ux * zz;
        float xz = ux * zy - uy * zx;
        // In the parent (shoulder) frame: rot^T * [X Y Z].
        float m00 = rot[0] * xx + rot[3] * xy + rot[6] * xz;
        float m10 = rot[1] * xx + rot[4] * xy + rot[7] * xz;
        float m20 = rot[2] * xx + rot[5] * xy + rot[8] * xz;
        float m11 = rot[1] * ux + rot[4] * uy + rot[7] * uz;
        float m21 = rot[2] * ux + rot[5] * uy + rot[8] * uz;
        float m12 = rot[1] * zx + rot[4] * zy + rot[7] * zz;
        float m22 = rot[2] * zx + rot[5] * zy + rot[8] * zz;
        float yAngle = (float) Math.asin(Mth.clamp(-m20, -1.0F, 1.0F));
        if (Mth.cos(yAngle) > 1.0E-4F) {
            solvedX = (float) Math.atan2(m21, m22);
            solvedZ = (float) Math.atan2(m10, m00);
        } else {
            solvedX = (float) Math.atan2(-m12, m11);
            solvedZ = 0.0F;
        }
        solvedY = yAngle;
        solvedBend = -(float) Math.acos(Mth.clamp(fu, -1.0F, 1.0F));
    }

    /**
     * The centre of its face (model pixels) as posed right now; the renderer turns it into a world
     * position for the kill camera and for sounds that come out of its mouth.
     */
    void faceCenter(float[] out) {
        frame(faceChain, 5);
        out[0] = origin[0] + rot[1] * -4.0F + rot[2] * -7.0F;
        out[1] = origin[1] + rot[4] * -4.0F + rot[5] * -7.0F;
        out[2] = origin[2] + rot[7] * -4.0F + rot[8] * -7.0F;
    }
}
